class ProbabilisticGrammar:
  def __init__(
    self, T: set[str], N: set[str], P: set[tuple[str, str, str]], S: str
  ):
    self.T, self.N, self.P, self.p, self.S = (
      T,
      N,
      {A: [] for A in N},
      {A: [] for A in N},
      S,
    )
    for A, τ, q in P:
      self.P[A].append(τ)
      self.p[A].append(Decimal(q))

  def L(self, log=False, stats=False) -> Iterator[str]:
    dd, d, p = [], [self.S], {self.S: Decimal(1)}
    if log:
      print('    ', self.S, '@', 1)
    while d != []:
      if stats:
        print('# added derivations:', len(d))
      if log:
        print()
      dd.extend(d)
      d = []
      for π in dd:
        A = next(
          (x for x in π.split() if x in self.N), None
        )  # find the first nonterminal
        if A != None:
          for τ, q in zip(self.P[A], self.p[A]):  # productions A → τ @ q
            χ = π.replace(A, τ, 1).replace('  ', ' ').strip()
            if (χ not in dd) and (χ not in d):
              d.append(χ)
              p[χ] = p[χ] + p[π] * q if χ in p else p[π] * q
              if all(a in self.T for a in χ.split()):
                yield χ, str(p[χ])
              if log:
                print('    ', π, '⇒ᴸ', χ, '@', p[χ])
